1	"use client";
2	
3	import {
4	  createContext,
5	  useCallback,
6	  useContext,
7	  useEffect,
8	  useState,
9	  type ReactNode,
10	} from "react";
11	import {
12	  getWorkspace,
13	  importWorkspace as apiImportWorkspace,
14	  type ApiError,
15	  type ImportWorkspaceRequest,
16	  type LocalWorkspaceSummary,
17	  type WorkspaceDetail,
18	} from "@/services/workflow-backend";
19	import {
20	  getLocalWorkspaceSummaries,
21	  getSelectedWorkspaceId,
22	  saveLocalWorkspaceSummary,
23	  removeLocalWorkspaceSummary,
24	  setSelectedWorkspaceId,
25	} from "@/services/local-workspace-store";
26	
27	export type WorkspaceContextValue = {
28	  summaries: LocalWorkspaceSummary[];
29	  selectedWorkspaceId: string | null;
30	  activeWorkspace: WorkspaceDetail | null;
31	  loadingWorkspace: boolean;
32	  workspaceError: ApiError | null;
33	  importingWorkspace: boolean;
34	  importError: ApiError | null;
35	
36	  selectWorkspace: (workspaceId: string) => void;
37	  importWorkspace: (body: ImportWorkspaceRequest) => Promise<void>;
38	  clearImportError: () => void;
39	  removeLocalSummary: (workspaceId: string) => void;
40	};
41	
42	const WorkspaceContext = createContext<WorkspaceContextValue | null>(null);
43	
44	export function WorkspaceProvider({ children }: { children: ReactNode }) {
45	  const [summaries, setSummaries] = useState<LocalWorkspaceSummary[]>([]);
46	  const [selectedWorkspaceId, setSelectedWorkspaceIdState] = useState<string | null>(null);
47	  const [activeWorkspace, setActiveWorkspace] = useState<WorkspaceDetail | null>(null);
48	  const [loadingWorkspace, setLoadingWorkspace] = useState(false);
49	  const [workspaceError, setWorkspaceError] = useState<ApiError | null>(null);
50	  const [importingWorkspace, setImportingWorkspace] = useState(false);
51	  const [importError, setImportError] = useState<ApiError | null>(null);
52	
53	  useEffect(() => {
54	    const storedSummaries = getLocalWorkspaceSummaries();
55	    const storedId = getSelectedWorkspaceId();
56	    setSummaries(storedSummaries);
57	
58	    const workspaceId =
59	      storedId ??
60	      storedSummaries.sort(
61	        (a, b) =>
62	          new Date(b.last_opened_at).getTime() -
63	          new Date(a.last_opened_at).getTime(),
64	      )[0]?.workspaceId ??
65	      null;
66	
67	    if (workspaceId) {
68	      setSelectedWorkspaceIdState(workspaceId);
69	      loadWorkspace(workspaceId);
70	    }
71	  }, []);
72	
73	  const loadWorkspace = useCallback((workspaceId: string) => {
74	    setLoadingWorkspace(true);
75	    setWorkspaceError(null);
76	    getWorkspace(workspaceId)
77	      .then((detail) => {
78	        setActiveWorkspace(detail);
79	        setLoadingWorkspace(false);
80	      })
81	      .catch((err: ApiError) => {
82	        setWorkspaceError(err);
83	        setLoadingWorkspace(false);
84	      });
85	  }, []);
86	
87	  const selectWorkspace = useCallback(
88	    (workspaceId: string) => {
89	      setSelectedWorkspaceIdState(workspaceId);
90	      setSelectedWorkspaceId(workspaceId);
91	      setActiveWorkspace(null);
92	
93	      const summary = summaries.find((s) => s.workspaceId === workspaceId);
94	      if (summary) {
95	        const updated: LocalWorkspaceSummary = {
96	          ...summary,
97	          last_opened_at: new Date().toISOString(),
98	        };
99	        saveLocalWorkspaceSummary(updated);
100	        setSummaries(getLocalWorkspaceSummaries());
101	      }
102	
103	      loadWorkspace(workspaceId);
104	    },
105	    [summaries, loadWorkspace],
106	  );
107	
108	  const importWorkspaceFn = useCallback(
109	    async (body: ImportWorkspaceRequest) => {
110	      setImportingWorkspace(true);
111	      setImportError(null);
112	      try {
113	        const detail = await apiImportWorkspace(body);
114	
115	        const repoUrl = body.repo_url;
116	        const urlParts = repoUrl.replace(/\.git$/, "").split("/");
117	        const repoName = urlParts[urlParts.length - 1] ?? repoUrl;
118	
119	        const summary: LocalWorkspaceSummary = {
120	          workspaceId: detail.id,
121	          name: detail.name || body.name || repoName,
122	          repo_url: body.repo_url,
123	          default_branch: body.default_branch ?? "main",
124	          last_opened_at: new Date().toISOString(),
125	        };
126	        saveLocalWorkspaceSummary(summary);
127	        setSelectedWorkspaceId(detail.id);
128	        setSummaries(getLocalWorkspaceSummaries());
129	        setSelectedWorkspaceIdState(detail.id);
130	        setActiveWorkspace(detail);
131	      } catch (err) {
132	        setImportError(err as ApiError);
133	        throw err;
134	      } finally {
135	        setImportingWorkspace(false);
136	      }
137	    },
138	    [],
139	  );
140	
141	  const clearImportError = useCallback(() => {
142	    setImportError(null);
143	  }, []);
144	
145	  const removeLocalSummary = useCallback((workspaceId: string) => {
146	    removeLocalWorkspaceSummary(workspaceId);
147	    setSummaries(getLocalWorkspaceSummaries());
148	    if (selectedWorkspaceId === workspaceId) {
149	      const remaining = getLocalWorkspaceSummaries();
150	      const next = remaining[0] ?? null;
151	      if (next) {
152	        setSelectedWorkspaceIdState(next.workspaceId);
153	        setSelectedWorkspaceId(next.workspaceId);
154	        loadWorkspace(next.workspaceId);
155	      } else {
156	        setSelectedWorkspaceIdState(null);
157	        setActiveWorkspace(null);
158	      }
159	    }
160	  }, [selectedWorkspaceId, loadWorkspace]);
161	
162	  return (
163	    <WorkspaceContext.Provider
164	      value={{
165	        summaries,
166	        selectedWorkspaceId,
167	        activeWorkspace,
168	        loadingWorkspace,
169	        workspaceError,
170	        importingWorkspace,
171	        importError,
172	        selectWorkspace,
173	        importWorkspace: importWorkspaceFn,
174	        clearImportError,
175	        removeLocalSummary,
176	      }}
177	    >
178	      {children}
179	    </WorkspaceContext.Provider>
180	  );
181	}
182	
183	export function useWorkspaceContext(): WorkspaceContextValue {
184	  const ctx = useContext(WorkspaceContext);
185	  if (!ctx) {
186	    throw new Error("useWorkspaceContext must be used within a WorkspaceProvider");
187	  }
188	  return ctx;
189	}
190

