54	export function WorkspaceSwitcher() {
55	  const { summaries, selectedWorkspaceId, selectWorkspace } = useWorkspaceContext();
56	  const [open, setOpen] = useState(false);
57	  const [showImport, setShowImport] = useState(false);
58	  const [search, setSearch] = useState("");
59	  const ref = useRef<HTMLDivElement>(null);
60	
61	  const filteredSummaries = summaries.filter(
62	    (s) =>
63	      !search ||
64	      s.name.toLowerCase().includes(search.toLowerCase()) ||
65	      s.repo_url.toLowerCase().includes(search.toLowerCase()),
66	  );
67	
68	  const handleSelect = useCallback(
69	    (workspaceId: string) => {
70	      if (workspaceId !== selectedWorkspaceId) {
71	        selectWorkspace(workspaceId);
72	      }
73	      setOpen(false);
74	      setSearch("");
75	    },
76	    [selectedWorkspaceId, selectWorkspace],
77	  );
78	
79	  const handleImportSuccess = useCallback(() => {
80	    setShowImport(false);
81	    setOpen(false);
82	    setSearch("");
83	  }, []);
