86	    if (!open) return;
87	    function handlePointerDown(e: PointerEvent) {
88	      if (!ref.current?.contains(e.target as Node)) {
89	        setOpen(false);
90	        setSearch("");
91	      }
92	    }
93	    document.addEventListener("pointerdown", handlePointerDown);
94	    return () => document.removeEventListener("pointerdown", handlePointerDown);
95	  }, [open]);
96	
97	  const activeSummary = summaries.find((s) => s.workspaceId === selectedWorkspaceId);
98	
99	  return (
100	    <>
